mapper.select:
select A.BOOKSET_ID as booksetId, B.BOOKSET_NAME as booksetName, C.BUSI_ID as bondId, D.FINPROD_ABBR as bondName, to_char(A.HAPPEN_DATE,'yyyy-mm-dd') as vdate, (A.END_DAYS_COST_AMT-A.TDY_COST_AMT) as changeAmt, A.DAILYDSC_YIELD as realRate, D.TRADE_MARKET as market from BOK_STAT_DET_POSIITON A, BOK_BOOKSET B , BOK_DETAIL_ID C , FIN_PRODUCT D where A.BOOKSET_ID=B.BOOKSET_ID and A.BOOKSET_ID=C.BOOKSET_ID and A.BOK_DETAIL_ID=C.BOK_DETAIL_ID and C.BUSI_ID=D.FINPROD_ID
and D.FINPROD_TYPE=#{finprodType}
and C.INV_AIM !=#{invAim}
and A.BOOKSET_ID=#{booksetId}
and C.BUSI_ID=#{bondId}
and A.HAPPEN_DATE >= to_date(#{vDateBegin},'yyyy-mm-dd')
and A.HAPPEN_DATE <= to_date(#{vDateEnd},'yyyy-mm-dd')
and D.TRADE_MARKET=#{market}
